using FiberRoute.App;
using FiberRoute.Core;
using System.Reflection;
static class R14UiChecks
{
    const BindingFlags Hidden=BindingFlags.NonPublic|BindingFlags.Instance;
    public static async Task Run(MainForm form,Store store,string output,Action<bool,string> check,Func<int,Task> idle,Action<string> shot)
    {
        T Field<T>(string name)=>(T)typeof(MainForm).GetField(name,Hidden)!.GetValue(form)!;
        object? Call(string name,params object?[] args)=>typeof(MainForm).GetMethod(name,Hidden)!.Invoke(form,args);
        async Task Settle(){await idle(300);for(int i=0;i<40&&Field<bool>("busy");i++)await idle(100);}
        List<Control> Walk(Control root){var list=new List<Control>{root};foreach(Control child in root.Controls)list.AddRange(Walk(child));return list;}
        void Size(Control pager,int index){var combo=(ComboBox)pager.GetType().GetField("size",Hidden)!.GetValue(pager)!;combo.SelectedIndex=index;}
        void Header(DataGridView grid,string column){var c=grid.Columns[column];typeof(DataGridView).GetMethod("OnColumnHeaderMouseClick",Hidden)!.Invoke(grid,[new DataGridViewCellMouseEventArgs(c.Index,-1,5,5,new MouseEventArgs(MouseButtons.Left,1,5,5,0))]);}
        string path=Path.Combine(output,"r14-paging.csv");List<object?[]> rows=[["ID","始端设施","终端设施","长度","空闲数量","中继纤芯数量","始端区域","终端区域","业务状态"]];
        for(int i=0;i<230;i++)rows.Add(["r14-"+i,$"{(i==0?"":"龙湖区")}用于核对长名称完整换行显示的示例机房第{i:000}栋二楼设施/ODF{i:000}",$"终端机房第{i:000}栋/ODF01",i+1,i%4+1,8,i==0?"":i%2==0?"龙湖区":"澄海区","潮南区",i%2==0?"在网":"在建"]);
        Csv.Write(path,rows);await store.ImportAsync(path,"自动",Store.Fields.ToDictionary(f=>f,f=>f),1,null,default);Call("RefreshData");await Settle();var tabs=Field<TabControl>("tabs");tabs.SelectedIndex=1;await Settle();var resources=Field<DataGridView>("resourceGrid");var pager=Field<Control>("resourcePager");Size(pager,0);await Settle();
        check(resources.Rows.Count==20,"resource every-page size selector applies 20 rows");var next=(Button)pager.GetType().GetField("next",Hidden)!.GetValue(pager)!;next.PerformClick();await Settle();check((int)resources.Rows[0].Cells["序号"].Value==21,"modern pager next page selects the correct global row range");
        var jump=(TextBox)pager.GetType().GetField("jump",Hidden)!.GetValue(pager)!;jump.Text="12";Walk(pager).OfType<Button>().Single(b=>b.Text=="确定").PerformClick();await Settle();check(resources.Rows.Count==10&&(int)resources.Rows[0].Cells["序号"].Value==221,"modern pager rounded page input reaches final partial page");
        Header(resources,"长度米");await Settle();Header(resources,"长度米");await Settle();check(Convert.ToDouble(resources.Rows[0].Cells["长度米"].Value)==230&&resources.Columns["长度米"].HeaderCell.SortGlyphDirection==SortOrder.Descending,"resource header sorts the full result before pagination and shows descending feedback");
        Field<ComboBox>("resourceStartArea").SelectedItem="未提供";await Settle();check(resources.Rows.Count==1&&(string)resources.Rows[0].Cells["始端区域"].Value=="未提供"&&(string)resources.Rows[0].Cells["终端区域"].Value=="潮南区","area filtering preserves missing values and separate endpoint regions");Field<ComboBox>("resourceStartArea").SelectedItem="全部区域";await Settle();
        resources.Columns["始端设施"].Width=120;Call("RememberGrid",resources);resources.Columns["始端设施"].Width=100;await idle(300);check(resources.Rows[0].Height>70,"long multiline facility rows grow after a persisted column is narrowed");resources.Columns["始端设施"].Width=260;Call("RememberGrid",resources);await idle(200);shot("R1.4-中继段资源-实际运行");
        string name=store.Graph.Nodes[0].Name;string evidence=Path.Combine(output,"R14来源复核.csv");Csv.Write(evidence,new object?[][]{["设施名称","所属区县","机房名称"],[name,"龙湖区","挂墙测试001"]});store.ApplyRoomFiles([(evidence,"机房",null)]);
        var nodes=store.Graph.Nodes;var groups=Enumerable.Range(1,25).Select(i=>new ClusterRecord("r14-group-"+i,"分页测试集群"+i,"机房",[nodes[i*2].Name,nodes[i*2+1].Name],"人工修改","已确认","",true)).Append(new("r14-review","需要核对的测试集群","机房",[nodes[1].Name,"不存在的成员"],"集群表：集群管理.xlsx","已确认","",true));store.SaveClusters(groups);Call("RefreshData");await Settle();tabs.SelectedIndex=2;var inner=Field<TabControl>("maintenanceTabs");inner.SelectedIndex=0;Size(Field<Control>("typePager"),0);await idle(250);var types=Field<DataGridView>("typeGrid");check(types.Rows.Count==20&&types.Columns.Contains("区域"),"node list exposes explicit region column and every-page selector");check(types.Rows[0].Height>=50&&types.Rows[0].Cells["名称"].FormattedValue?.ToString()?.Contains('\n')==true,"node long names wrap into visible multiline cells without losing the underlying identity");shot("R1.4-节点类型-实际运行");
        inner.SelectedIndex=1;await idle(200);var clusterChips=Field<FlowLayoutPanel>("clusterStatusChips");clusterChips.Controls.OfType<Button>().Single(b=>(string?)b.Tag=="需核对").PerformClick();await idle(200);var clusters=Field<DataGridView>("clusterGrid");check(clusters.Rows.Count>0&&clusters.Rows.Cast<DataGridViewRow>().All(r=>(string)r.Cells["确认状态"].Value=="需核对"),"cluster review chip immediately filters effective abnormal items");check(Call("SelectedCluster") is ClusterRecord selected&&selected.Id==(string)clusters.CurrentRow!.Cells["内部标识"].Value,"cluster selection uses stable identity rather than an old page row number");shot("R1.4-集群管理-实际运行");
        clusterChips.Controls.OfType<Button>().Single(b=>(string?)b.Tag=="全部").PerformClick();Size(Field<Control>("clusterPager"),0);await idle(200);check(clusters.Rows.Count==20,"cluster list supports selectable paging instead of binding the entire collection");
        inner.SelectedIndex=2;await idle(200);var roomChips=Field<FlowLayoutPanel>("roomStatusChips");roomChips.Controls.OfType<Button>().Single(b=>(string?)b.Tag=="需核对").PerformClick();await idle(200);var rooms=Field<DataGridView>("roomGrid");check(rooms.Rows.Count==1&&(string)rooms.Rows[0].Cells["归并状态"].Value=="已暂停"&&(int)rooms.Rows[0].Cells["已纳入"].Value==0,"room review list quarantines wall locations from logical contraction");check(Field<TextBox>("roomDetails").Text.Contains("R14来源复核.csv")&&Field<TextBox>("roomDetails").Text.Contains("第 2 行"),"room details display actual filename, field and original record row");shot("R1.4-机房归属-实际运行");
        check(new[]{"resourcePager","typePager","clusterPager","roomPager"}.All(n=>!Walk(Field<Control>(n)).OfType<NumericUpDown>().Any()),"all four pagers use styled text inputs without native spinner arrows");
        using var settings=(Form)Call("BuildSettingsDialog")!;settings.Show(form);await idle(250);var controls=Walk(settings);controls.OfType<Button>().Single(b=>b.Text=="检测软件更新").PerformClick();await idle(150);controls.OfType<Button>().Single(b=>b.Text=="检测数据更新").PerformClick();await idle(150);check(controls.OfType<Label>().Count(l=>l.Text=="更新服务未配置")==2,"both update buttons distinguish an unconfigured service without claiming online readiness");
        using(var bitmap=new Bitmap(settings.ClientSize.Width,settings.ClientSize.Height)){using(var graphics=Graphics.FromImage(bitmap))graphics.CopyFromScreen(settings.PointToScreen(Point.Empty),Point.Empty,settings.ClientSize);bitmap.Save(Path.Combine(output,"R1.4-设置-实际运行.png"));}settings.Close();
    }
}
